WITH exploded AS (SELECT id, plan, effective_from, currency, EXPLODE(tier_limits) AS tier_value FROM price_tiers) SELECT *, CUME_DIST() OVER w_hist AS tier_value_cume_dist, DENSE_RANK() OVER (PARTITION BY plan ORDER BY tier_value NULLS FIRST) AS tier_value_dense_rank, CUME_DIST() OVER (PARTITION BY plan, currency ORDER BY tier_value DESC NULLS FIRST) AS tier_value_cume_dist_2, CUME_DIST() OVER (PARTITION BY plan, currency ORDER BY tier_value NULLS LAST) AS tier_value_cume_dist_3 FROM exploded WINDOW w_hist AS (PARTITION BY currency ORDER BY tier_value DESC NULLS FIRST);
